M(bf, r"""
public static int bmRead(String key) {
  if (key == null || key.length() == 0) return -1;
  int lv = -1;
  String why = "SkyySkills' skill:fn:run is not loaded";
  try {
    BM_READS.incrementAndGet();
    java.util.function.Function f = @PKG@.PetsLog.fn("skill:fn:run");
    if (f != null) {
      Object o = f.apply(new Object[] { key, BM_SKILL });
      why = "skill:fn:run has no Beastmastery level (SkyySkills older than 0.4.60?)";
      if (o instanceof Object[]) {
        Object[] a = (Object[]) o;
        boolean same = a.length < 6 || a[5] == null || BM_SKILL.equalsIgnoreCase(String.valueOf(a[5]).trim());
        if (a.length >= 1 && a[0] instanceof Number && same) lv = ((Number) a[0]).intValue();
      }
    }
  } catch (Throwable t) { lv = -1; why = "skill:fn:run failed: " + t; }
  if (lv < 0) {
    lv = -1;
    if (!BM_WARNED) { BM_WARNED = true; @PKG@.PetsLog.warn("summon slot (Beastmastery level mode): " + why + " - summon slots not opened by a quest stay locked (logged once)"); }
  }
  return lv;
}""")
M(bf, r"""
public static int bmCached(String key, long now, boolean force) {
  if (key == null) return -1;
  Object o = BMLV.get(key);
  if (!force && o instanceof long[]) {
    long[] c = (long[]) o;
    if (now >= c[0] && now - c[0] < BM_TTL) return (int) c[1];
  }
  int lv = bmRead(key);
  if (BMLV.size() > 4096) BMLV.clear();
  BMLV.put(key, new long[] { now, (long) lv });
  return lv;
}""")
M(bf, r"""
public static int bmLevel(@PKG@.PetRec r) {
  if (r == null || r.key == null) return -1;
  return bmCached(r.key, System.currentTimeMillis(), false);
}""")
